import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_naive_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv3d_naive_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int depth_in,
    const int height_in,
    const int width_in,
    const int depth_out,
    const int height_out,
    const int width_out,
    const int kernel_size,
    const int stride,
    const int padding,
    const bool use_bias
) {
    int total_threads = batch_size * out_channels * depth_out * height_out * width_out;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_threads) return;

    // Decode idx into (b, oc, od, oh, ow)
    int out_id = idx;
    int ow = out_id % width_out;
    out_id /= width_out;
    int oh = out_id % height_out;
    out_id /= height_out;
    int od = out_id % depth_out;
    out_id /= depth_out;
    int oc = out_id % out_channels;
    int b = out_id / out_channels;

    // Compute starting input indices
    int d_in_start = od * stride - padding;
    int h_in_start = oh * stride - padding;
    int w_in_start = ow * stride - padding;

    float val = 0.0f;
    // Naive convolution loop
    for(int ic = 0; ic < in_channels; ic++){
        for(int kd = 0; kd < kernel_size; kd++){
            for(int kh = 0; kh < kernel_size; kh++){
                for(int kw = 0; kw < kernel_size; kw++){
                    int d_in = d_in_start + kd;
                    int h_in = h_in_start + kh;
                    int w_in = w_in_start + kw;
                    if(d_in >= 0 && d_in < depth_in &&
                       h_in >= 0 && h_in < height_in &&
                       w_in >= 0 && w_in < width_in){
                        int input_idx = b * (in_channels * depth_in * height_in * width_in)
                                      + ic * (depth_in * height_in * width_in)
                                      + d_in * (height_in * width_in)
                                      + h_in * width_in
                                      + w_in;
                        int weight_idx = oc * (in_channels * kernel_size * kernel_size * kernel_size)
                                       + ic * (kernel_size * kernel_size * kernel_size)
                                       + kd * (kernel_size * kernel_size)
                                       + kh * kernel_size
                                       + kw;
                        val += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }
    }
    if (use_bias) {
        val += bias[oc];
    }
    output[idx] = val;
}

torch::Tensor conv3d_naive_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding
) {
    const bool use_bias = (bias.numel() > 0);

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int depth_in = input.size(2);
    int height_in = input.size(3);
    int width_in = input.size(4);

    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    // Compute output dimensions (assuming square kernel & stride/pad for all dims)
    int depth_out = (depth_in + 2 * padding - kernel_size) / stride + 1;
    int height_out = (height_in + 2 * padding - kernel_size) / stride + 1;
    int width_out = (width_in + 2 * padding - kernel_size) / stride + 1;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::empty({batch_size, out_channels, depth_out, height_out, width_out}, options);

    int total_threads = batch_size * out_channels * depth_out * height_out * width_out;
    const int block = 256;
    const int grid = (total_threads + block - 1) / block;

    conv3d_naive_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        depth_in,
        height_in,
        width_in,
        depth_out,
        height_out,
        width_out,
        kernel_size,
        stride,
        padding,
        use_bias
    );
    return output;
}
''';

conv3d_naive_cpp_source = "torch::Tensor conv3d_naive_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding);"

conv3d_naive = load_inline(
    name="conv3d_naive",
    cpp_sources=conv3d_naive_cpp_source,
    cuda_sources=conv3d_naive_source,
    functions=["conv3d_naive_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Custom 3D convolution using a naïve CUDA implementation.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, 
                 padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        # For simplicity, ignoring 'dilation' and 'groups' in custom kernel
        # Storing relevant parameters
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

        # Create learnable parameters
        self.weight = nn.Parameter(
            torch.randn(out_channels, in_channels, kernel_size, kernel_size, kernel_size, 
                        device='cuda', dtype=torch.float32) * 0.01
        )
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels, device='cuda', dtype=torch.float32))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.bias is None:
            bias = torch.zeros((0,), device=x.device, dtype=x.dtype)
        else:
            bias = self.bias
        return conv3d_naive.conv3d_naive_cuda(x, self.weight, bias, self.stride, self.padding)
